inference_trace:
Process the hits in reverse with a union-find (DSU) that has a virtual "roof" node.

1. **Remove all hit bricks first.** Copy the grid. For each hit, set the cell to 0, but remember whether a brick was originally there.
2. **Build the DSU on the remaining bricks.**
   - Union each brick with its brick neighbors.
   - Union every brick in row 0 with the roof node, whose index is `m*n`.
3. **Add the hit bricks back in reverse order.** For each hit, from last to first:
   - If there was no brick originally, the answer is 0.
   - Otherwise, record `prev = size(find(roof))`.
   - Restore the brick. If it is in row 0, union it with the roof. Union it with its 4 neighbors that are bricks.
   - Record `now = size(find(roof))`.
   - The answer is `max(0, now - prev - 1)`. The `-1` excludes the restored brick itself.

The reverse step works because, going backwards, the bricks that become newly connected to the roof are exactly the ones that fell when that brick was hit.

A note on the duplicate check: hits are unique, so no extra handling is needed. A hit on an empty cell simply leaves the copy at 0.

```cpp
class Solution {
public:
    vector<int> par, sz;
    int find(int x){ while(par[x]!=x){ par[x]=par[par[x]]; x=par[x]; } return x; }
    void unite(int a,int b){ a=find(a); b=find(b); if(a==b) return; if(sz[a]<sz[b]) swap(a,b); par[b]=a; sz[a]+=sz[b]; }
    vector<int> hitBricks(vector<vector<int>>& grid, vector<vector<int>>& hits) {
        int m=grid.size(), n=grid[0].size();
        vector<vector<int>> g=grid;
        for(auto&h:hits) g[h[0]][h[1]]=0;
        int roof=m*n;
        par.resize(m*n+1); sz.assign(m*n+1,1);
        for(int i=0;i<=m*n;i++) par[i]=i;
        for(int i=0;i<m;i++) for(int j=0;j<n;j++) if(g[i][j]){
            if(i==0) unite(j,roof);
            if(i>0&&g[i-1][j]) unite(i*n+j,(i-1)*n+j);
            if(j>0&&g[i][j-1]) unite(i*n+j,i*n+j-1);
        }
        int k=hits.size();
        vector<int> res(k,0);
        int dx[4]={1,-1,0,0}, dy[4]={0,0,1,-1};
        for(int t=k-1;t>=0;t--){
            int r=hits[t][0], c=hits[t][1];
            if(!grid[r][c]) continue;
            int prev=sz[find(roof)];
            g[r][c]=1;
            if(r==0) unite(c,roof);
            for(int d=0;d<4;d++){
                int nr=r+dx[d], nc=c+dy[d];
                if(nr<0||nc<0||nr>=m||nc>=n||!g[nr][nc]) continue;
                unite(r*n+c,nr*n+nc);
            }
            int now=sz[find(roof)];
            res[t]=max(0,now-prev-1);
        }
        return res;
    }
};
```

