Count how often each character appears, then check that every non-zero count matches the first non-zero count seen. Using a 256-entry array keeps the count safe even if stray characters (like the trailing spaces in the examples) show up.

```cpp
class Solution {
public:
    bool areOccurrencesEqual(string s) {
        int cnt[256] = {0};
        for (unsigned char c : s) cnt[c]++;
        int f = 0;
        for (int i = 0; i < 256; i++) {
            if (cnt[i] == 0) continue;
            if (f == 0) f = cnt[i];
            else if (cnt[i] != f) return false;
        }
        return true;
    }
};
```

