Use Kahn's algorithm on the reversed graph:

1. Build the reverse adjacency list, and record each node's out-degree in the original graph.
2. Push every terminal node (out-degree 0) onto a queue.
3. Pop a node and mark it safe. For each of its predecessors, decrement that predecessor's out-degree. When a predecessor's out-degree reaches 0, all its outgoing edges lead to safe nodes, so push it onto the queue.
4. Collect the safe nodes by scanning indices in ascending order, which gives a sorted result.

Nodes that lie on a cycle, or that can reach a cycle, never have their out-degree drop to 0, so they are never marked safe.

```cpp
class Solution {
public:
    vector<int> eventualSafeNodes(vector<vector<int>>& graph) {
        int n = graph.size();
        vector<vector<int>> rev(n);
        vector<int> outdeg(n);
        for (int i = 0; i < n; i++) {
            outdeg[i] = graph[i].size();
            for (int j : graph[i]) rev[j].push_back(i);
        }
        vector<int> q;
        for (int i = 0; i < n; i++) if (outdeg[i] == 0) q.push_back(i);
        vector<bool> safe(n, false);
        for (size_t h = 0; h < q.size(); h++) {
            int u = q[h];
            safe[u] = true;
            for (int p : rev[u]) {
                if (--outdeg[p] == 0) q.push_back(p);
            }
        }
        vector<int> res;
        for (int i = 0; i < n; i++) if (safe[i]) res.push_back(i);
        return res;
    }
};
```

