Use Fenwick trees over the value range 1..100000. One tree counts how many times each value appears in the window, and a second tree sums the values. A queue holds the last m elements, so each add is O(log V).

For a query, define f(t) as the sum of the t smallest elements in the window. The answer is (f(m−k) − f(k)) / (m − 2k).

To compute f(t):
1. Binary-lift on the count tree to find the largest position `pos` whose prefix count is less than t.
2. Read `cnt` and `sum` from both trees at that position.
3. The value `pos+1` fills the remaining `t − cnt` slots, so f(t) = sum + (t − cnt)·(pos+1).

Sums can reach about 1e10, so use long long.

```cpp
class MKAverage {
    static const int N = 100001;
    int m, k, LOG;
    vector<long long> cntT, sumT;
    queue<int> q;
    void upd(int i, long long c, long long s) {
        for (; i < N; i += i & -i) { cntT[i] += c; sumT[i] += s; }
    }
    long long f(long long t) {
        int pos = 0;
        long long cnt = 0, sum = 0;
        for (int b = LOG; b > 0; b >>= 1) {
            int np = pos + b;
            if (np < N && cnt + cntT[np] < t) {
                pos = np;
                cnt += cntT[np];
                sum += sumT[np];
            }
        }
        return sum + (t - cnt) * (long long)(pos + 1);
    }
public:
    MKAverage(int m, int k) : m(m), k(k), cntT(N, 0), sumT(N, 0) {
        LOG = 1;
        while (LOG * 2 < N) LOG *= 2;
    }

    void addElement(int num) {
        q.push(num);
        upd(num, 1, num);
        if ((int)q.size() > m) {
            int x = q.front(); q.pop();
            upd(x, -1, -x);
        }
    }

    int calculateMKAverage() {
        if ((int)q.size() < m) return -1;
        return (int)((f(m - k) - f(k)) / (m - 2 * k));
    }
};
```

