Use a bitmask DP over the set of elements already removed.

- Let `m = nums.size()` (at most 14), so there are at most 2^14 masks.
- `dp[mask]` is the best score after removing exactly the elements marked in `mask`.
- The popcount of `mask` is always even. The next operation index is `popcount(mask) / 2 + 1`.
- From a valid `mask`, pick any two unused elements `i` and `j`. Then update `dp[mask | (1<<i) | (1<<j)]` with `dp[mask] + op * gcd(nums[i], nums[j])`.
- Precompute all pairwise gcds once, so each transition is O(1).

Total work is about 2^14 × 14² ≈ 3.2M transitions, which is fast.

Unreachable states start at -1 and are skipped. The answer is `dp[full]`, where every element has been removed.

```cpp
class Solution {
public:
    int maxScore(vector<int>& nums) {
        int m = nums.size();
        vector<vector<int>> g(m, vector<int>(m));
        for (int i = 0; i < m; i++)
            for (int j = 0; j < m; j++)
                g[i][j] = __gcd(nums[i], nums[j]);
        int full = 1 << m;
        vector<int> dp(full, -1);
        dp[0] = 0;
        for (int mask = 0; mask < full; mask++) {
            if (dp[mask] < 0) continue;
            int c = __builtin_popcount(mask);
            if (c & 1) continue;
            int op = c / 2 + 1;
            for (int i = 0; i < m; i++) {
                if (mask & (1 << i)) continue;
                for (int j = i + 1; j < m; j++) {
                    if (mask & (1 << j)) continue;
                    int nm = mask | (1 << i) | (1 << j);
                    dp[nm] = max(dp[nm], dp[mask] + op * g[i][j]);
                }
            }
        }
        return dp[full - 1];
    }
};
```

