class Solution {
public:
    long long maxRunTime(int n, vector<int>& batteries) {
        long long sum = 0;
        for (int b : batteries) sum += b;
        long long lo = 0, hi = sum / n;
        while (lo < hi) {
            long long mid = lo + (hi - lo + 1) / 2;
            long long s = 0;
            for (int b : batteries) s += min((long long)b, mid);
            if (s >= (long long)n * mid) lo = mid;
            else hi = mid - 1;
        }
        return lo;
    }
};
```

