Use slow and fast pointers. Both start at `head`; each step moves `slow` one node and `fast` two nodes. When `fast` reaches the end (it is null, or its `next` is null), `slow` sits at the middle.

For an even-length list, this lands on the second of the two middle nodes, which is what the problem asks for. For example, with 6 nodes, `slow` stops at node 4.

This runs in O(n) time and O(1) extra space.

```cpp
/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    ListNode* middleNode(ListNode* head) {
        ListNode* slow = head;
        ListNode* fast = head;
        while (fast && fast->next) {
            slow = slow->next;
            fast = fast->next->next;
        }
        return slow;
    }
};
```

