- The answer is never more than 2. Some land cell can always be cut off by removing at most two of its neighbors (for example, a corner-most cell).
- If the grid already has 0 islands or 2 or more, it is already disconnected, so the answer is 0.
- Otherwise, try removing each land cell in turn and recount the islands. If any single removal leaves a count other than 1, the answer is 1.
  - This also covers the one-cell case: removing it leaves 0 islands, which counts as disconnected, so the answer is 1.
- If no single removal works, the answer is 2.

Cost: there are at most 900 cells, and each recount is O(900), so about 810k steps. That is fine.

The island count uses an iterative DFS with a visited array.

```cpp
class Solution {
public:
    int m, n;
    int count(vector<vector<int>>& g) {
        vector<vector<char>> vis(m, vector<char>(n, 0));
        int c = 0;
        int dx[4] = {1,-1,0,0}, dy[4] = {0,0,1,-1};
        for (int i = 0; i < m; i++) for (int j = 0; j < n; j++) {
            if (g[i][j] == 1 && !vis[i][j]) {
                c++;
                vector<pair<int,int>> st;
                st.push_back({i,j});
                vis[i][j] = 1;
                while (!st.empty()) {
                    auto [x,y] = st.back(); st.pop_back();
                    for (int d = 0; d < 4; d++) {
                        int nx = x+dx[d], ny = y+dy[d];
                        if (nx>=0&&ny>=0&&nx<m&&ny<n&&g[nx][ny]==1&&!vis[nx][ny]) {
                            vis[nx][ny]=1;
                            st.push_back({nx,ny});
                        }
                    }
                }
            }
        }
        return c;
    }
    int minDays(vector<vector<int>>& grid) {
        m = grid.size(); n = grid[0].size();
        if (count(grid) != 1) return 0;
        for (int i = 0; i < m; i++) for (int j = 0; j < n; j++) {
            if (grid[i][j] == 1) {
                grid[i][j] = 0;
                int c = count(grid);
                grid[i][j] = 1;
                if (c != 1) return 1;
            }
        }
        return 2;
    }
};
```

