        for (int j = 0; j < n; j++) {
            for (int k = j + 1; k < n; k++) {
                long long p = (long long)b[j] * b[k];
                auto it = sq.find(p);
                if (it != sq.end()) res += it->second;
            }
        }
        return res;
    }
    int numTriplets(vector<int>& nums1, vector<int>& nums2) {
