Walk the spiral directly and record only the cells that fall inside the grid.

1. Start at `(rStart, cStart)`, record it, and face east.
2. The spiral's segment lengths follow the pattern 1, 1, 2, 2, 3, 3, ... — the length grows by one after every two turns.
3. Turn clockwise in the order east, south, west, north.
4. For each step, if the new cell is inside the grid, add it to the result.
5. Stop once `rows * cols` cells have been collected.

```cpp
class Solution {
public:
    vector<vector<int>> spiralMatrixIII(int rows, int cols, int rStart, int cStart) {
        vector<vector<int>> res;
        int dr[4] = {0, 1, 0, -1};
        int dc[4] = {1, 0, -1, 0};
        int r = rStart, c = cStart;
        res.push_back({r, c});
        int total = rows * cols;
        int len = 1, d = 0;
        while ((int)res.size() < total) {
            for (int k = 0; k < 2 && (int)res.size() < total; k++) {
                for (int s = 0; s < len; s++) {
                    r += dr[d];
                    c += dc[d];
                    if (r >= 0 && r < rows && c >= 0 && c < cols) {
                        res.push_back({r, c});
                    }
                }
                d = (d + 1) % 4;
            }
            len++;
        }
        return res;
    }
};
```

