inference_trace:
Insert every word into a trie in reverse order. Keep the stream as a growing string. On each query, append the letter and walk the trie from the newest character backwards. Return true as soon as we reach a node that marks the end of a word. Stop early if the path breaks or we have gone 200 characters back, since no word is longer than that.

The trie can have up to 400,000 nodes (2000 words × 200 characters). To keep this compact, the nodes are stored in flat arrays of child indices instead of separately allocated objects.

Cost:
- Each query walks at most 200 steps.
- With 4×10⁴ queries, that is at most 8×10⁶ steps in total.

```cpp
class StreamChecker {
public:
    vector<array<int,26>> ch;
    vector<bool> term;
    string s;
    int maxLen = 0;
    StreamChecker(vector<string>& words) {
        ch.push_back({});
        ch[0].fill(0);
        term.push_back(false);
        for (auto& w : words) {
            maxLen = max(maxLen, (int)w.size());
            int cur = 0;
            for (int i = (int)w.size() - 1; i >= 0; --i) {
                int c = w[i] - 'a';
                if (!ch[cur][c]) {
                    ch[cur][c] = ch.size();
                    array<int,26> a; a.fill(0);
                    ch.push_back(a);
                    term.push_back(false);
                }
                cur = ch[cur][c];
            }
            term[cur] = true;
        }
    }

    bool query(char letter) {
        s.push_back(letter);
        int cur = 0;
        int n = s.size();
        for (int i = n - 1; i >= 0 && n - i <= maxLen; --i) {
            int c = s[i] - 'a';
            cur = ch[cur][c];
            if (!cur) return false;
            if (term[cur]) return true;
        }
        return false;
    }
};
```

