inference_trace:
Approach: fill in digits column by column, starting from the least significant digit, and backtrack as soon as a column can't work.

1. **Clean input.** Keep only uppercase letters, so stray spaces like `"SEND "` are ignored.
2. **Quick rejection.** If any word is longer than `result`, the sum can't fit, so return `false`.
3. **Leading-zero rule.** Mark the first letter of every string with length greater than 1 as unable to be 0.
4. **Search with `dfs(col, row, sum)`.**
   - `col` is the current column, counted from the right.
   - `row` is the current word being processed.
   - `sum` is the running column sum, including the carry from the previous column.
5. **Words in the column.** For each word that has a letter in this column:
   - If the letter already has a digit, add it to `sum`.
   - Otherwise, try every unused digit for it (skipping 0 if it is a leading letter).
6. **Result letter.** After all words in the column, the result's letter there must equal `sum % 10`.
   - If it already has a digit, that digit must match.
   - Otherwise, assign `sum % 10` to it, provided the digit is unused and the leading-zero rule allows it.
   - Then move to the next column with carry `sum / 10`.
7. **Finish.** After the last column of `result`, the remaining carry must be 0.

Checking each column as soon as it is complete prunes most bad assignments early.

```cpp
class Solution {
public:
    vector<string> w;
    string r;
    int mp[26];
    bool used[10];
    bool lead[26];
    int n;

    bool dfs(int col, int row, int sum) {
        int rl = r.size();
        if (col == rl) return sum == 0;
        if (row < n) {
            const string& s = w[row];
            int len = s.size();
            if (col >= len) return dfs(col, row + 1, sum);
            int c = s[len - 1 - col] - 'A';
            if (mp[c] >= 0) return dfs(col, row + 1, sum + mp[c]);
            for (int d = 0; d < 10; d++) {
                if (used[d]) continue;
                if (d == 0 && lead[c]) continue;
                used[d] = true; mp[c] = d;
                if (dfs(col, row + 1, sum + d)) return true;
                used[d] = false; mp[c] = -1;
            }
            return false;
        }
        int c = r[rl - 1 - col] - 'A';
        int d = sum % 10;
        if (mp[c] >= 0) {
            if (mp[c] != d) return false;
            return dfs(col + 1, 0, sum / 10);
        }
        if (used[d]) return false;
        if (d == 0 && lead[c]) return false;
        used[d] = true; mp[c] = d;
        if (dfs(col + 1, 0, sum / 10)) return true;
        used[d] = false; mp[c] = -1;
        return false;
    }

    bool isSolvable(vector<string>& words, string result) {
        auto clean = [](const string& s) {
            string t;
            for (char ch : s) if (ch >= 'A' && ch <= 'Z') t += ch;
            return t;
        };
        w.clear();
        for (auto& s : words) w.push_back(clean(s));
        r = clean(result);
        n = w.size();
        for (auto& s : w) if (s.size() > r.size()) return false;
        memset(mp, -1, sizeof(mp));
        memset(used, 0, sizeof(used));
        memset(lead, 0, sizeof(lead));
        for (auto& s : w) if (s.size() > 1) lead[s[0] - 'A'] = true;
        if (r.size() > 1) lead[r[0] - 'A'] = true;
        return dfs(0, 0, 0);
    }
};
```

